def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    last_me, last_opp = history[-1]
    if last_opp == 'D' and last_me == 'C':
        opp_defects = sum(1 for _, o in history if o == 'D')
        if opp_defects >= 3 and opp_defects * 2 >= n:
            return 'D'
        return 'D'

    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')

    if n >= 96:
        if opp_defects * 4 <= n:
            return 'D'
        return 'D'

    if opp_defects == 0:
        return 'C'

    if opp_defects >= 3 and opp_defects * 3 >= n:
        return 'D'

    recent = history[-6:]
    recent_opp_d = sum(1 for _, o in recent if o == 'D')
    if recent_opp_d >= 3:
        return 'D'

    if my_defects > opp_defects + 2:
        return 'C'

    if last_me == 'D' and last_opp == 'C':
        return 'C'

    return 'C'
